CREATE SCHEMA "insite";

CREATE TABLE "insite"."flha" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "job_id"          bigint                   NOT NULL,
  "hazards"         jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "acknowledgement" boolean                  NOT NULL DEFAULT false,
  "submitted_by"    text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "flha_pkey" PRIMARY KEY (id)
);

ALTER TABLE "insite"."flha"
  ENABLE ROW LEVEL SECURITY;

CREATE TYPE "insite"."flha_rating" AS ENUM (
  'acceptable',
  'low',
  'medium',
  'high',
  'n/a'
);

ALTER TABLE "insite"."flha"
  ADD CONSTRAINT "flha_job_id_fkey" FOREIGN KEY (job_id) REFERENCES public.jobs(id) ON DELETE CASCADE;

CREATE INDEX idx_flha_hazards_gin ON insite.flha USING gin (hazards);

CREATE INDEX idx_flha_job_id ON insite.flha USING btree (job_id);

CREATE TRIGGER set_updated_at
  BEFORE UPDATE ON insite.flha
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_updated_at();

CREATE POLICY "Enable insert for authenticated users" ON "insite"."flha"
  FOR INSERT
  TO PUBLIC
  WITH CHECK ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable read access for authenticated users" ON "insite"."flha"
  FOR SELECT
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text));

CREATE POLICY "Enable update for authenticated users" ON "insite"."flha"
  FOR UPDATE
  TO PUBLIC
  USING ((auth.role() = 'authenticated'::text))
  WITH CHECK ((auth.role() = 'authenticated'::text));

COMMENT ON SCHEMA "insite" IS 'Insite mobile app schema';

GRANT USAGE ON SCHEMA "insite" TO PUBLIC, "anon", "authenticated", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "insite"."flha" TO "anon", "authenticated", "service_role";
